import{z as s,x as o,o as e,c as m,q as n,j as B,D as t,d as r,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"布朗运动与伊藤引理","description":"","frontmatter":{"title":"布朗运动与伊藤引理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/brownian-ito.md","filePath":"econ/brownian-ito.md","lastUpdated":1791063341000}'),d={name:"econ/brownian-ito.md"};function p(C,a,f,h,u,F){const A=o("Mermaid");return e(),m("div",null,[a[2]||(a[2]=n('<h1 id="布朗运动与伊藤引理" tabindex="-1">布朗运动与伊藤引理 <a class="header-anchor" href="#布朗运动与伊藤引理" aria-label="Permalink to &quot;布朗运动与伊藤引理&quot;">​</a></h1><div class="epigraph"><p>路径连续、二次变差按时间线性积累时，一阶泰勒不够：微分必须带上 $\\frac12\\sigma^2$ 的那一项。</p><footer>—— 据 Itô；对照 Merton 连续时间金融对引理的用法</footer></div><p><a href="/econ/demand-system-asset-pricing">上一课</a>仍在离散份额与特征。本单元换装置：连续时间。缺口是把后文组合与均衡要用的微积分钉死——布朗运动与伊藤引理——而不先写最优。摩擦课序的约束先关掉，以便把随机积分写干净。不是随机过程教科书，只留资产定价用到的那一刀。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散多期的财富是和；连续极限里，收益有漂移与扩散。标准布朗 \\(B_t\\) 路径连续、几乎处处不可微，二次变差 \\(\\langle B\\rangle_t=t\\)。于是复合函数 \\(f(t,X)\\) 在 \\(X\\) 为伊藤过程时，</p> \\[\\mathrm{d}f=f_t\\,\\mathrm{d}t+f_x\\,\\mathrm{d}X+\\tfrac12 f_{xx}\\,\\mathrm{d}\\langle X\\rangle. \\]<p>漏掉最后一项，财富与价格的动力学全错——Black–Scholes 的偏微、Merton 的预算，都靠它。缺口不是证明维纳过程存在，而是：后课默认读者会用二次变差记账。</p><p><span class="marginnote">布朗是工作噪声源。跳跃会加一个泊松积分，伊藤公式多出跳项；不完全市场后课再提。本课先无跳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>伊藤过程 \\(\\mathrm{d}X=\\mu\\,\\mathrm{d}t+\\sigma\\,\\mathrm{d}B\\)。乘法：\\(X\\) 为价格时，\\(\\mathrm{d}X/X\\) 的积分是几何布朗，对数要减 \\(\\tfrac12\\sigma^2\\)。这解释「平均回报」与「对数均值」差一项，后面组合的目标函数必须说清楚用哪一个。随机积分 \\(\\int\\theta\\,\\mathrm{d}B\\) 是局部鞅（再加可积则鞅），对应 FTAP 在连续时间的「对冲增益」。动态完备课已经口头说过一个布朗配一个风险资产；本课把「一个」落实为维数。</p>',10)),(e(),B(l,null,{default:t(()=>[i(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20BM%5B%22%E5%B8%83%E6%9C%97%3A%20%E8%BF%9E%E7%BB%AD%2C%20%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%20%3D%20t%22%5D%20--%3E%20ITO%5B%22%E4%BC%8A%E8%97%A4%3A%20%E5%A4%9A%201%2F2%20f_xx%20d%EF%BC%9CX%3E%22%5D%0A%20%20ITO%20--%3E%20GEO%5B%22%E5%87%A0%E4%BD%95%E5%B8%83%E6%9C%97%E7%9A%84%E5%AF%B9%E6%95%B0%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20ITO%20--%3E%20BDGT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E8%B4%A2%E5%AF%8C%E5%8A%A8%E5%8A%9B%E5%AD%A6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把 \\(\\sigma\\,\\mathrm{d}B\\) 写成限价簿的瞬时冲击。扩散是均衡或外生价格过程的理想化；\\(\\lambda\\) 是信息租金。装置不同。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：\\(\\sigma=20\\%\\) 时，\\(\\tfrac12\\sigma^2=0.02\\)：一只「算术平均年回报 8%」的股票，对数的年均漂移约是 \\(0.08-0.02=6\\%\\)。波动越大，算术平均与几何平均的缺口越大——这一项不是笔误，是波动的价钱。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"机制是二次变差的确定性积累。高频的小冲击平方起来变成 \\(\\sigma^2\\mathrm{d}t\\)，对凹函数（效用、对数价格）产生 Jensen 项。风险厌恶在连续时间里通过这一项进入，而不必先写离散的方差。Girsanov 改漂移、不改 \\(\\sigma\\)，故对冲仍用 \\(\\sigma\\)——这是后文 BS 作为复制的伏笔：复制看波动，不管 \\(\\mathbb{P}\\) 下的 \\(\\mu\\)。",-1)),a[7]||(a[7]=E("p",null,"与等价鞅测度：在 \\(\\mathbb{Q}\\) 下漂移被扭到 \\(r\\)，伊藤公式照用。本课在 \\(\\mathbb{P}\\) 下先会写微分。",-1)),a[8]||(a[8]=E("p",null,[E("span",{class:"marginnote"},"Itô 公式对凸函数给出严格的 Jensen 修正。Jensen 在离散课已有；连续时间把它变成微分方程的系数。")],-1)),(e(),B(l,null,{default:t(()=>[i(A,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E6%8A%8A%E4%B8%80%E5%B9%B4%E5%88%87%E6%88%90%20n%20%E4%B8%AA%E5%B0%8F%E6%A0%BC%2C%20%E6%AF%8F%E6%A0%BC%20%CE%94t%22%5D%20--%3E%20INC%5B%22%E6%AF%8F%E6%A0%BC%E5%99%AA%E5%A3%B0%E5%A2%9E%E9%87%8F%20%CE%94B%20%E7%9A%84%E9%87%8F%E7%BA%A7%E6%98%AF%E6%A0%B9%E5%8F%B7%CE%94t%22%5D%0A%20%20INC%20--%3E%20SQ%5B%22%E5%B9%B3%E6%96%B9%E5%90%8E%20(%CE%94B)%C2%B2%20%E2%89%88%20%CE%94t%2C%20%E9%9A%8F%E6%9C%BA%E7%AC%A6%E5%8F%B7%E8%A2%AB%E6%8A%B9%E5%B9%B3%22%5D%0A%20%20SQ%20--%3E%20SUM%5B%22n%20%E6%A0%BC%E6%B1%82%E5%92%8C%20%E2%89%88%20t%3A%20%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%9C%B0%E5%8C%80%E9%80%9F%E7%A7%AF%E7%B4%AF%22%5D%0A%20%20SUM%20--%3E%20TAY%5B%22%E6%B3%B0%E5%8B%92%E4%BA%8C%E9%98%B6%E9%A1%B9%20(1%2F2)f''%20%CF%83%C2%B2%20dt%20%E5%8D%87%E6%A0%BC%E4%B8%BA%E6%AD%A3%E5%BC%8F%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20TAY%20--%3E%20LOG%5B%22%E5%87%B9%E5%87%BD%E6%95%B0(%E5%AF%B9%E6%95%B0%2C%20%E6%95%88%E7%94%A8)%E8%A2%AB%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%8E%8B%E4%BD%8E%E8%BF%99%E4%B8%80%E9%A1%B9%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=n('<p>这张图回答的是：普通泰勒展开里可以扔掉的二阶小量，为什么在连续时间下死不掉。噪声增量的平方不再随机，而是按 \\(\\sigma^2\\mathrm{d}t\\) 像水表一样匀速走字；求和不抵消、只累积，于是二阶项获得与一阶项同阶的地位——伊藤引理的全部增量都在这一步。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲测度论条件、不证明存在。下一课把引理接到预算：消费与组合如何驱动财富过程。没有预算，伊藤只是微积分。</p><p><span class="marginnote">常见误区：初学者容易把布朗路径想象成光滑曲线，套普通链式法则。实际上它处处不可微——在二次变差不为零的世界里用普通微积分，期权定价和财富动学会被系统性地算错。</span></p><p>后课默认：价格与财富用伊藤过程；微分含二次变差项；一个布朗是一个独立风险源。跳跃另说。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>布朗路径连续但二次变差为 \\(t\\)；伊藤引理多 \\(\\frac12 f_{xx}\\)。</li><li>几何布朗的对数均值减 \\(\\tfrac12\\sigma^2\\)；随机积分是对冲增益。</li><li>扩散不是盘口冲击，是连续时间装置。</li><li>出处：Itô 公式；Merton 连续时间金融的用法。</li></ul>',7))])}const g=s(d,[["render",p]]);export{b as __pageData,g as default};
